# Let's manually analyze the pairs to understand the patterns
inputs = ['hyfw', 'ceb', 'bagg', 'hiecf', 'ihafx']
outputs = ['uaayfw', 'cdxedjuaa', 'djuaaagg', 'uaaidxecf', 'cxafx']

print("Input -> Output pairs:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

print("\nAnalyzing differences:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"{inp} -> {outp}")
    # Show where they differ
    for j in range(max(len(inp), len(outp))):
        if j >= len(inp):
            print(f"  Position {j}: added '{outp[j]}'")
        elif j >= len(outp):
            print(f"  Position {j}: removed '{inp[j]}'")
        elif inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

